cd /home/electronica-care/ezy-prep/exam/app && python3 - <<'EOF'
p='src/app/(app)/leases/[leaseId]/page.tsx'
s=open(p).read()
s=s.replace('import Link from "next/link";\n','import Link from "next/link";\nimport { Suspense } from "react";\n',1)
s=s.replace('import { PaymentActions }','import { LeaseDetailSkeleton } from "@/components/staff/skeletons";\nimport { PaymentActions }',1)
s=s.replace('import { loadCaller } from "@/server/access";','import { loadCaller, requireLeaseAccess } from "@/server/access";',1)
old_start=s.index('  const ctx = { userId };')
old_end=s.index('  const { lease, invoices, payments } = detail;')
new_head='''  // Access check runs before any JSX is returned, so a 404 is a real 404 and not a 200 already flushed by
  // Suspense streaming (D72). Other org, other tenant, nonexistent or malformed id all look the same (R38).
  try {
    await requireLeaseAccess(caller, leaseId, ["manager", "staff"]);
  } catch (e) {
    if (e instanceof ApiError && (e.status === 404 || e.status === 403)) notFound();
    throw e;
  }

  return (
    <Suspense fallback={<LeaseDetailSkeleton />}>
      <LeaseDetail
        userId={userId}
        leaseId={leaseId}
        isManager={caller.member.role === "manager"}
        orgId={caller.member.orgId}
      />
    </Suspense>
  );
}

async function LeaseDetail({
  userId,
  leaseId,
  isManager,
  orgId,
}: {
  userId: string;
  leaseId: string;
  isManager: boolean;
  orgId: string;
}) {
  const ctx = { userId };
  let detail: Awaited<ReturnType<typeof getLease>>;
  try {
    detail = await getLease(ctx, leaseId);
  } catch (e) {
    if (e instanceof ApiError && (e.status === 404 || e.status === 403)) notFound();
    throw e;
  }
'''
s=s[:old_start]+new_head+s[old_end:]
s=s.replace('''  const isManager = caller.member.role === "manager";
  // A lease the caller can open belongs to the caller's org, so that org is the slip folder (R44).
  const orgId = caller.member.orgId;
''','''  // A lease the caller can open belongs to the caller's org, so that org is the slip folder (R44).
''',1)
open(p,'w').write(s)
open('src/components/staff/skeletons.tsx','a').write('''
export function LeaseDetailSkeleton() {
  return (
    <div aria-busy="true" aria-label="Loading lease">
      <Skeleton className="mb-6 h-16" />
      <div className="grid gap-4 sm:grid-cols-3">
        <Skeleton className="h-24" />
        <Skeleton className="h-24" />
        <Skeleton className="h-24" />
      </div>
      <Skeleton className="mt-6 h-64" />
    </div>
  );
}
''')
EOF

